  1→package dashboard
  2→
  3→import (
  4→	"fmt"
  5→	"strings"
  6→
  7→	tea "github.com/charmbracelet/bubbletea"
  8→
  9→	"github.com/entireio/cli/cmd/entire/cli/strategy"
 10→)
 11→
 12→//nolint:recvcheck // bubbletea pattern: pointer receivers for mutating setters, value receivers for update/view
 13→type checkpointsModel struct {
 14→	points     []strategy.RewindPoint
 15→	filtered   []strategy.RewindPoint
 16→	err        error
 17→	cursor     int
 18→	scrollPos  int
 19→	width      int
 20→	height     int
 21→	showDetail bool
 22→	filtering  bool
 23→	filter     string
 24→	confirming bool // rewind confirmation dialog
 25→}
 26→
 27→func newCheckpointsModel() checkpointsModel {
 28→	return checkpointsModel{}
 29→}
 30→
 31→func (m *checkpointsModel) setSize(width, height int) {
 32→	m.width = width
 33→	m.height = height
 34→}
 35→
 36→func (m *checkpointsModel) setCheckpoints(points []strategy.RewindPoint) {
 37→	m.points = points
 38→	m.applyFilter()
 39→}
 40→
 41→func (m *checkpointsModel) applyFilter() {
 42→	if m.filter == "" {
 43→		m.filtered = m.points
 44→		return
 45→	}
 46→	lower := strings.ToLower(m.filter)
 47→	var filtered []strategy.RewindPoint
 48→	for _, p := range m.points {
 49→		if strings.Contains(strings.ToLower(p.ID), lower) ||
 50→			strings.Contains(strings.ToLower(p.Message), lower) ||
 51→			strings.Contains(strings.ToLower(p.SessionPrompt), lower) ||
 52→			strings.Contains(strings.ToLower(p.CheckpointID.String()), lower) {
 53→			filtered = append(filtered, p)
 54→		}
 55→	}
 56→	m.filtered = filtered
 57→	if m.cursor >= len(m.filtered) {
 58→		m.cursor = max(0, len(m.filtered)-1)
 59→	}
 60→}
 61→
 62→func (m checkpointsModel) update(msg tea.Msg) (checkpointsModel, tea.Cmd) {
 63→	keyMsg, ok := msg.(tea.KeyMsg)
 64→	if !ok {
 65→		return m, nil
 66→	}
 67→
 68→	// Handle confirmation dialog
 69→	if m.confirming {
 70→		switch keyMsg.String() {
 71→		case keyY, keyYUpper:
 72→			m.confirming = false
 73→			if m.cursor < len(m.filtered) {
 74→				point := m.filtered[m.cursor]
 75→				return m, func() tea.Msg {
 76→					return rewindRequestMsg{pointID: point.ID}
 77→				}
 78→			}
 79→		case keyN, keyNUpper, keyEsc:
 80→			m.confirming = false
 81→		}
 82→		return m, nil
 83→	}
 84→
 85→	// Handle filter input
 86→	if m.filtering {
 87→		switch keyMsg.String() {
 88→		case keyEsc:
 89→			m.filtering = false
 90→			m.filter = ""
 91→			m.applyFilter()
 92→		case keyEnter:
 93→			m.filtering = false
 94→		case keyBackspace:
 95→			if len(m.filter) > 0 {
 96→				m.filter = m.filter[:len(m.filter)-1]
 97→				m.applyFilter()
 98→			}
 99→		default:
100→			if len(keyMsg.String()) == 1 {
101→				m.filter += keyMsg.String()
102→				m.applyFilter()
103→			}
104→		}
105→		return m, nil
106→	}
107→
108→	switch keyMsg.String() {
109→	case keyJ, keyDown:
110→		if m.showDetail {
111→			m.scrollPos++
112→		} else if m.cursor < len(m.filtered)-1 {
113→			m.cursor++
114→		}
115→	case keyK, keyUp:
116→		if m.showDetail {
117→			if m.scrollPos > 0 {
118→				m.scrollPos--
119→			}
120→		} else if m.cursor > 0 {
121→			m.cursor--
122→		}
123→	case keyEnter:
124→		if len(m.filtered) > 0 {
125→			m.showDetail = !m.showDetail
126→			m.scrollPos = 0
127→		}
128→	case keyEsc:
129→		if m.showDetail {
130→			m.showDetail = false
131→			m.scrollPos = 0
132→		} else if m.filter != "" {
133→			m.filter = ""
134→			m.applyFilter()
135→		}
136→	case keyFilter:
137→		m.filtering = true
138→	case keyR:
139→		if len(m.filtered) > 0 && !m.showDetail {
140→			m.confirming = true
141→		}
142→	}
143→
144→	return m, nil
145→}
146→
147→func (m checkpointsModel) view(width, height int) string {
148→	if m.err != nil {
149→		return errorStyle.Render(fmt.Sprintf("Error loading checkpoints: %v", m.err))
150→	}
151→
152→	if m.confirming && m.cursor < len(m.filtered) {
153→		return m.renderConfirmation(width, height)
154→	}
155→
156→	if m.showDetail && m.cursor < len(m.filtered) {
157→		return m.renderDetail(width, height)
158→	}
159→
160→	return m.renderList(width, height)
161→}
162→
163→func (m checkpointsModel) renderList(_ int, height int) string {
164→	var lines []string
165→
166→	// Header
167→	headerText := fmt.Sprintf("Checkpoints (%d)", len(m.filtered))
168→	if m.filter != "" {
169→		headerText += "  filter: " + m.filter
170→	}
171→	if m.filtering {
172→		headerText += dimStyle.Render("  type to filter, Enter to confirm, Esc to cancel")
173→	}
174→	lines = append(lines, "  "+titleStyle.Render(headerText))
175→	lines = append(lines, "")
176→
177→	if len(m.filtered) == 0 {
178→		lines = append(lines, "  "+dimStyle.Render("No checkpoints found"))
179→		return strings.Join(lines, "\n")
180→	}
181→
182→	for i, p := range m.filtered {
183→		cpType := cpTypeSession
184→		if p.IsTaskCheckpoint {
185→			cpType = cpTypeTask
186→		}
187→		if p.IsLogsOnly {
188→			cpType = cpTypeCommitted
189→		}
190→
191→		cpID := p.CheckpointID.String()
192→		if cpID == "" {
193→			cpID = truncate(p.ID, 12)
194→		}
195→
196→		prompt := truncate(p.SessionPrompt, 40)
197→		if prompt == "" {
198→			prompt = truncate(p.Message, 40)
199→		}
200→
201→		agentStr := string(p.Agent)
202→		if agentStr == "" {
203→			agentStr = "-"
204→		}
205→
206→		line := fmt.Sprintf("  %-12s  %-10s  %-14s  %-10s  %s",
207→			cpID,
208→			dimStyle.Render("["+cpType+"]"),
209→			agentStr,
210→			dimStyle.Render(timeAgo(p.Date)),
211→			prompt,
212→		)
213→
214→		if i == m.cursor {
215→			line = selectedItemStyle.Render(line)
216→		}
217→
218→		lines = append(lines, line)
219→	}
220→
221→	// Scroll
222→	visibleStart := 0
223→	headerLines := 2
224→	maxVisible := height - headerLines
225→	if maxVisible < 1 {
226→		maxVisible = 1
227→	}
228→
229→	if m.cursor-visibleStart >= maxVisible {
230→		visibleStart = m.cursor - maxVisible + 1
231→	}
232→
233→	result := lines[:headerLines]
234→	dataLines := lines[headerLines:]
235→	end := visibleStart + maxVisible
236→	if end > len(dataLines) {
237→		end = len(dataLines)
238→	}
239→	if visibleStart < len(dataLines) {
240→		result = append(result, dataLines[visibleStart:end]...)
241→	}
242→
243→	return strings.Join(result, "\n")
244→}
