 11→
 12→//nolint:recvcheck // bubbletea pattern: pointer receivers for mutating setters, value receivers for update/view
 13→type activeModel struct {
 14→	states     []*session.State
 15→	err        error
 16→	cursor     int
 17→	scrollPos  int
 18→	width      int
 19→	height     int
 20→	showDetail bool
 21→}
 22→
 23→func newActiveModel() activeModel {
 24→	return activeModel{}
 25→}
 26→
 27→func (m *activeModel) setSize(width, height int) {
 28→	m.width = width
 29→	m.height = height
 30→}
 31→
 32→func (m *activeModel) setSessions(states []*session.State) {
 33→	// Filter to active sessions only (no EndedAt)
 34→	var active []*session.State
 35→	for _, s := range states {
 36→		if s.EndedAt == nil {
 37→			active = append(active, s)
 38→		}
 39→	}
 40→	m.states = active
 41→}
 42→
 43→func (m activeModel) update(msg tea.Msg) (activeModel, tea.Cmd) { //nolint:unparam // tea.Cmd needed for consistent tab interface
 44→	if keyMsg, ok := msg.(tea.KeyMsg); ok {
 45→		switch keyMsg.String() {
 46→		case keyJ, keyDown:
 47→			if m.showDetail {
 48→				m.scrollPos++
 49→			} else if m.cursor < len(m.states)-1 {
 50→				m.cursor++
 51→			}
 52→		case keyK, keyUp:
 53→			if m.showDetail {
 54→				if m.scrollPos > 0 {
 55→					m.scrollPos--
 56→				}
 57→			} else if m.cursor > 0 {
 58→				m.cursor--
 59→			}
 60→		case keyEnter:
 61→			if len(m.states) > 0 {
 62→				m.showDetail = !m.showDetail
 63→				m.scrollPos = 0
 64→			}
 65→		case keyEsc:
 66→			m.showDetail = false
 67→			m.scrollPos = 0
 68→		}
 69→	}
 70→	return m, nil
 71→}
 72→
 73→func (m activeModel) view(width, height int) string {
 74→	if m.err != nil {
 75→		return errorStyle.Render(fmt.Sprintf("Error loading active sessions: %v", m.err))
 76→	}
 77→	if len(m.states) == 0 {
 78→		return dimStyle.Render("  No active sessions")
 79→	}
 80→
 81→	if m.showDetail && m.cursor < len(m.states) {
 82→		return m.renderDetail(width, height)
 83→	}
 84→
 85→	return m.renderList(width, height)
 86→}
